(function($) {
    $.fn.jCarouselLite = function(o) {
        o = $.extend({
            btnPrev: null, btnNext: null, btnGo: null, mouseWheel: false, 
            auto: null, speed: 200, easing: null, vertical: false, 
            circular: true, visible: 5, start: 0, scroll: 1, 
            beforeStart: null, play: true, afterEnd: null
        }, o || {});
        
        return this.each(function() {
            var b = false, animCss = o.vertical ? "top" : "left", 
                sizeCss = o.vertical ? "height" : "width";
            
            var c = $(this), ul = $("ul", c), tLi = $("li", ul), 
                tl = tLi.length, v = o.visible; // 修复点1：.size() -> .length

            // 修复点2：.bind() -> .on()
            ul.on("mouseover", function() {
                if (o.play) o.play = false;
            }).on("mouseout", function() {
                if (!o.play) o.play = true;
            });

            if (o.circular) {
                ul.prepend(tLi.slice(tl - v - 1 + 1).clone()).append(tLi.slice(0, v).clone());
                o.start += v;
            }

            var f = $("li", ul), itemLength = f.length, curr = o.start; // 修复点3
            c.css("visibility", "visible");
            
            // 样式设置保持不变
            f.css({ overflow: "hidden", float: o.vertical ? "none" : "left" });
            ul.css({ 
                margin: "0", padding: "0", 
                position: "relative", "list-style-type": "none", 
                "z-index": "1" 
            });
            c.css({ 
                overflow: "hidden", position: "relative", 
                "z-index": "2", left: "0px" 
            });

            var g = o.vertical ? height(f) : width(f);
            var h = g * itemLength;
            var j = g * v;
            
            f.css({ width: f.width(), height: f.height() });
            ul.css(sizeCss, h + "px").css(animCss, -(curr * g));
            c.css(sizeCss, j + "px");

            // 修复点4：.click() -> .on('click')
            if (o.btnPrev) $(o.btnPrev).on('click', function() {
                return go(curr - o.scroll);
            });

            if (o.btnNext) $(o.btnNext).on('click', function() {
                return go(curr + o.scroll);
            });

            if (o.btnGo) $.each(o.btnGo, function(i, a) {
                $(a).on('click', function() { 
                    return go(o.circular ? o.visible + i : i); 
                });
            });

            // 修复点5：mousewheel 插件需要单独引入（如果使用）
            if (o.mouseWheel && c.mousewheel) {
                c.on("mousewheel", function(e, d) { // 事件名称可能需适配插件
                    return d > 0 ? go(curr - o.scroll) : go(curr + o.scroll);
                });
            }

            if (o.auto) {
                setInterval(AutoPlay, o.auto + o.speed);
            }

            function vis() {
                return f.slice(curr).slice(0, v);
            }

            function AutoPlay() { 
                if (o.play) go(curr + o.scroll); 
            }

            function go(a) {
                if (!b) {
                    // 修复点6：添加严格类型检查
                    if (typeof o.beforeStart === "function") {
                        o.beforeStart.call(this, vis());
                    }

                    if (o.circular) {
                        if (a <= o.start - v - 1) {
                            ul.css(animCss, -((itemLength - (v * 2)) * g) + "px");
                            curr = a === o.start - v - 1 ? 
                                   itemLength - (v * 2) - 1 : 
                                   itemLength - (v * 2) - o.scroll;
                        } else if (a >= itemLength - v + 1) {
                            ul.css(animCss, -((v) * g) + "px");
                            curr = a === itemLength - v + 1 ? 
                                   v + 1 : 
                                   v + o.scroll;
                        } else {
                            curr = a;
                        }
                    } else {
                        if (a < 0 || a > itemLength - v) return;
                        else curr = a;
                    }

                    b = true;
                    ul.animate(
                        animCss === "left" ? { left: -(curr * g) } : { top: -(curr * g) },
                        {
                            duration: o.speed,
                            easing: o.easing,
                            complete: function() {
                                if (typeof o.afterEnd === "function") {
                                    o.afterEnd.call(this, vis());
                                }
                                b = false;
                            }
                        }
                    );

                    if (!o.circular) {
                        $(o.btnPrev + "," + o.btnNext).removeClass("disabled");
                        $((curr - o.scroll < 0 && o.btnPrev) || 
                          (curr + o.scroll > itemLength - v && o.btnNext) || 
                          []).addClass("disabled");
                    }
                }
                return false;
            }
        });
    };

    // 修复点7：使用现代方法获取尺寸
    function css(el, prop) {
        return parseInt($(el).css(prop), 10) || 0;
    }

    function width(el) {
        return el[0].offsetWidth + css(el, 'marginLeft') + css(el, 'marginRight');
    }

    function height(el) {
        return el[0].offsetHeight + css(el, 'marginTop') + css(el, 'marginBottom');
    }
})(jQuery);

/--------- 初始化代码保持不变 ---------------/
$(document).ready(function(){
    $("#cpzsm").jCarouselLite({
        btnPrev: "#prev",
        btnNext: "#next",
        auto: 4000,
        scroll: 5,
        speed: 500,
        vertical: false,
        visible: 5,
        circular: true
    });
});

